script:
// Mercury: gate the custom "Delivered" Task status.
//
// "Delivered" is added to Task.status by a Property Setter, which is DocType-wide -
// Frappe Select options are metadata, so an option cannot be offered to only some
// records. This script removes it from the dropdown unless the task's company has
// ticked "Allow Delivered Task Status".
//
// THIS IS COSMETIC. The real enforcement is server-side in mercury/task_status.py
// (doc_events -> Task.validate), because a REST call, a Data Import or
// frappe.db.set_value never runs this file. Do not delete that hook and rely on this.

const MERCURY_DELIVERED = "Delivered";

function mercury_apply_delivered_option(frm) {
    const field = frm.get_field("status");
    if (!field) return;

    const meta_field = frappe.get_meta("Task").fields.find(
        (f) => f.fieldname === "status"
    );
    const base = (meta_field.options || "").split("\n");

    const show = () => {
        field.df.options = base.join("\n");
        frm.refresh_field("status");
    };

    const hide = () => {
        // Never strip the option when the saved record already uses it - the control
        // would render blank and an ordinary save would silently clear the status.
        if (frm.doc.status === MERCURY_DELIVERED) return show();
        field.df.options = base
            .filter((o) => o !== MERCURY_DELIVERED)
            .join("\n");
        frm.refresh_field("status");
    };

    if (!frm.doc.company && !frm.doc.project) return hide();

    frappe.call({
        method: "mercury.task_status.is_delivered_allowed",
        args: { company: frm.doc.company, project: frm.doc.project },
        callback: (r) => (r.message ? show() : hide()),
    });
}

frappe.ui.form.on("Task", {
    refresh: mercury_apply_delivered_option,
    project: mercury_apply_delivered_option,
    company: mercury_apply_delivered_option,
});

// RTM approval workflow as a compact stepper inside the PAGE HEAD, between the
// document title and the action buttons.
// Draft -> Under Customer Review -> RTM Approved. "Revision Requested" is a BRANCH
// that loops back to review, so it is not drawn as a fourth step - the bar holds at
// step 2 and turns amber.

frappe.ui.form.on("Sales Order", {
    onload_post_render(frm) { queue_rtm_stepper(frm); },
    refresh(frm) { queue_rtm_stepper(frm); },
});

function queue_rtm_stepper(frm) {
    // the page head is redrawn after refresh, so wait for it to settle
    setTimeout(() => {
        try { render_rtm_stepper(frm); } catch (e) { console.error("RTM stepper:", e); }
    }, 200);
}

function render_rtm_stepper(frm) {
    $(".mercury-rtm-stepper").remove();

    const state = frm.doc.workflow_state;
    if (!state) return;

    const MAIN = ["Draft", "Submittal Under Customer Review", "RTM Approved"];
    const SHORT = { "Draft": "Draft",
                    "Submittal Under Customer Review": "Under Customer Review",
                    "RTM Approved": "RTM Approved" };
    const revising = state === "Revision Requested";
    let current = MAIN.indexOf(state);
    if (revising) current = 1;
    if (current < 0) return;

    let parts = [];
    MAIN.forEach((s, i) => {
        if (i) parts.push('<span class="mrs-line"></span>');
        const done = i < current;
        const active = i === current;
        const cls = done ? "done" : active ? (revising ? "warn" : "active") : "todo";
        const mark = done ? "&#10003;" : (i + 1);
        parts.push('<span class="mrs-step ' + cls + '">' +
                     '<span class="mrs-dot">' + mark + "</span>" +
                     '<span class="mrs-label">' + SHORT[s] + "</span>" +
                   "</span>");
    });
    if (revising) {
        parts.push('<span class="mrs-branch">&#8630; Revision Requested</span>');
    }

    const html =
      '<div class="mercury-rtm-stepper">' +
      "<style>" +
      ".mercury-rtm-stepper{display:inline-flex;align-items:center;gap:6px;" +
        "white-space:nowrap;vertical-align:middle;margin-left:14px}" +
      ".mercury-rtm-stepper .mrs-step{display:inline-flex;align-items:center;gap:5px}" +
      ".mercury-rtm-stepper .mrs-dot{display:inline-block;width:18px;height:18px;" +
        "line-height:16px;text-align:center;border-radius:50%;font-size:10px;font-weight:600;" +
        "background:var(--control-bg,#f4f5f6);color:var(--text-muted,#8d99a6);" +
        "border:1px solid var(--border-color,#d8dde3)}" +
      ".mercury-rtm-stepper .mrs-label{font-size:11px;color:var(--text-muted,#8d99a6)}" +
      // a real line, not a table cell - that is what rendered as grey blocks
      ".mercury-rtm-stepper .mrs-line{display:inline-block;width:26px;height:1px;" +
        "background:var(--border-color,#d8dde3)}" +
      ".mercury-rtm-stepper .done .mrs-dot{background:#2e7d32;border-color:#2e7d32;color:#fff}" +
      ".mercury-rtm-stepper .done .mrs-label{color:var(--text-color)}" +
      ".mercury-rtm-stepper .active .mrs-dot{background:#1f4e79;border-color:#1f4e79;color:#fff}" +
      ".mercury-rtm-stepper .active .mrs-label{color:var(--text-color);font-weight:600}" +
      ".mercury-rtm-stepper .warn .mrs-dot{background:#b26a00;border-color:#b26a00;color:#fff}" +
      ".mercury-rtm-stepper .warn .mrs-label{color:#b26a00;font-weight:600}" +
      ".mercury-rtm-stepper .mrs-branch{font-size:11px;font-weight:600;color:#b26a00;" +
        "background:#fff6e5;border:1px solid #f0dcb0;border-radius:10px;padding:1px 8px}" +
      "</style>" + parts.join("") + "</div>";

    // sit in the page head, just after the title / status pill
    const $head = $(frm.page.wrapper).find(".page-head");
    const anchors = [
        $head.find(".title-area").first(),
        $head.find(".page-title").first(),
        $head.find(".title-text").first().parent(),
    ];
    for (const $a of anchors) {
        if ($a && $a.length) { $a.append(html); return; }
    }
    console.warn("RTM stepper: no page-head anchor found");
}
